-- Expert Obby For Free - ALL IN ONE HOP VERSION
-- Walk to first pos + walk cycle + pause + stop + recording + serverhop to smallest + auto-rejoin on kick
-- Single file

local Players = game:GetService("Players")
local TeleportService = game:GetService("TeleportService")
local HttpService = game:GetService("HttpService")
local RunService = game:GetService("RunService")
local player = Players.LocalPlayer

-- Make script persist after hop
local queueteleport = queue_on_teleport or (syn and syn.queue_on_teleport) or (fluxus and fluxus.queue_on_teleport)
if queueteleport then
    queueteleport('loadstring(game:HttpGet("https://github.com/zeinscripts/Obby-For-Free/raw/refs/heads/main/exported_2464_FIXED_WALK_HOP.lua"))()')
end

local function getSmallestServer()
    local success, result = pcall(function()
        return game:HttpGet("https://games.roblox.com/v1/games/"..game.PlaceId.."/servers/Public?sortOrder=Asc&limit=100")
    end)
    if success then
        local ok, data = pcall(function() return HttpService:JSONDecode(result) end)
        if ok and data and data.data then
            local smallest = nil
            local minPlayers = 999
            for _, srv in ipairs(data.data) do
                if srv.playing < minPlayers and srv.id ~= game.JobId and srv.maxPlayers > srv.playing then
                    minPlayers = srv.playing
                    smallest = srv
                end
            end
            return smallest
        end
    end
    return nil
end

local function serverHop()
    print("🔄 Hopping to smallest server...")
    local smallest = getSmallestServer()
    if smallest then
        TeleportService:TeleportToPlaceInstance(game.PlaceId, smallest.id, player)
    else
        TeleportService:Teleport(game.PlaceId, player)
    end
end

-- Auto rejoin if kicked
pcall(function()
    game:GetService("CoreGui").RobloxPromptGui.promptOverlay.ChildAdded:Connect(function(child)
        if child.Name == "ErrorPrompt" then
            task.wait(2)
            local txt = ""
            pcall(function() txt = child:FindFirstChild("MessageArea").ErrorFrame.MessageLabel.Text end)
            if string.find(string.lower(txt), "banned") then return end
            serverHop()
        end
    end)
end)

TeleportService.TeleportInitFailed:Connect(function(p, result, err)
    if p == player then
        task.wait(2)
        serverHop()
    end
end)


local function fixCF(x,y,z,r00,r01,r02,r10,r11)
 local r12
 if math.abs(r02) > 0.001 then
  r12 = -(r00*r10 + r01*r11)/r02
  local len = math.sqrt(r10*r10 + r11*r11 + r12*r12)
  if len > 0.001 then r10/=len; r11/=len; r12/=len end
 else
  local l2 = r10*r10 + r11*r11
  if l2 <= 1 then r12 = -math.sqrt(math.max(0,1-l2)) else r12=0; local l=math.sqrt(l2); r10/=l; r11/=l end
 end
 local r20 = r01*r12 - r02*r11
 local r21 = r02*r10 - r00*r12
 local r22 = r00*r11 - r01*r10
 local l = math.sqrt(r20*r20+r21*r21+r22*r22)
 if l>0.001 then r20/=l; r21/=l; r22/=l end
 return CFrame.new(x,y,z,r00,r01,r02,r10,r11,r12,r20,r21,r22)
end

